import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import { CloudUpload as ImportIcon, Sync as SyncIcon } from '@mui/icons-material';
import apiService from '../../services/api';

interface SupplierRecord {
  _id: string;
  legalName: string;
  engagementStatus?: string;
  vendorAliases?: string[];
  contactEmail?: string;
}

interface SupplierSubmission {
  _id: string;
  supplierId?: { _id?: string; legalName?: string } | string;
  emissionFactorKgCo2ePerUnit?: number;
  emissionFactorKgCo2ePerInr?: number;
  totalKgCo2e?: number;
  status?: string;
}

interface UpstreamSummary {
  registeredSuppliers?: number;
  activeSubmissions?: number;
  upstreamSpendProxyCount?: number;
  upstreamSupplierPrimaryCount?: number;
  coveragePct?: number;
  suppliersMissingPrimaryData?: number;
  gaps?: Array<{
    supplierName: string;
    spendProxyTransactions: number;
    totalSpendInr: number;
  }>;
}

interface SupplierPrimaryDataPanelProps {
  summary?: UpstreamSummary;
  initialSuppliers?: SupplierRecord[];
  initialSubmissions?: SupplierSubmission[];
}

const SupplierPrimaryDataPanel: React.FC<SupplierPrimaryDataPanelProps> = ({
  summary,
  initialSuppliers = [],
  initialSubmissions = [],
}) => {
  const [suppliers, setSuppliers] = useState<SupplierRecord[]>(initialSuppliers);
  const [submissions, setSubmissions] = useState<SupplierSubmission[]>(initialSubmissions);
  const [legalName, setLegalName] = useState('');
  const [contactEmail, setContactEmail] = useState('');
  const [factorPerInr, setFactorPerInr] = useState('');
  const [selectedSupplierId, setSelectedSupplierId] = useState('');
  const [csvText, setCsvText] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [inviteUrl, setInviteUrl] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    const [supplierRes, submissionRes] = await Promise.all([
      apiService.getUpstreamSuppliers(),
      apiService.getSupplierEmissionSubmissions(),
    ]);
    if (supplierRes?.success && Array.isArray(supplierRes.data)) {
      setSuppliers(supplierRes.data);
    }
    if (submissionRes?.success && Array.isArray(submissionRes.data)) {
      setSubmissions(submissionRes.data);
    }
  }, []);

  useEffect(() => {
    if (!initialSuppliers.length) {
      refresh().catch(() => undefined);
    }
  }, [initialSuppliers.length, refresh]);

  const handleCreateSupplier = async () => {
    setLoading(true);
    setError(null);
    setMessage(null);
    try {
      const response = await apiService.createUpstreamSupplier({ legalName: legalName.trim() });
      if (!response?.success) {
        throw new Error(response?.message || 'Failed to create supplier');
      }
      setLegalName('');
      setMessage('Supplier registered.');
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create supplier');
    } finally {
      setLoading(false);
    }
  };

  const handleInviteSupplier = async () => {
    if (!legalName.trim() || !contactEmail.trim()) {
      setError('Enter supplier legal name and email to send an enrollment request.');
      return;
    }
    setLoading(true);
    setError(null);
    setMessage(null);
    setInviteUrl(null);
    try {
      const response = await apiService.inviteUpstreamSupplier({
        vendorName: legalName.trim(),
        contactEmail: contactEmail.trim(),
      });
      if (!response?.success) {
        throw new Error(response?.message || 'Failed to invite supplier');
      }
      const payload = (response.data || {}) as { inviteUrl?: string; emailSent?: boolean };
      setInviteUrl(payload.inviteUrl || null);
      setMessage(
        payload.emailSent
          ? 'Enrollment invite emailed to the supplier.'
          : 'Invite created — share the link below with your supplier.'
      );
      setContactEmail('');
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to invite supplier');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateSubmission = async () => {
    if (!selectedSupplierId || !factorPerInr) {
      setError('Select a supplier and enter kg CO₂e per INR.');
      return;
    }
    setLoading(true);
    setError(null);
    setMessage(null);
    try {
      const response = await apiService.createSupplierEmissionSubmission({
        supplierId: selectedSupplierId,
        submissionType: 'spend_factor',
        emissionFactorKgCo2ePerInr: Number(factorPerInr),
        dataQuality: 'supplier_primary',
      });
      if (!response?.success) {
        throw new Error(response?.message || 'Failed to save submission');
      }
      setFactorPerInr('');
      setMessage('Supplier emission factor saved.');
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save submission');
    } finally {
      setLoading(false);
    }
  };

  const handleImportCsv = async () => {
    setLoading(true);
    setError(null);
    setMessage(null);
    try {
      const response = await apiService.importSupplierEmissionSubmissions({
        format: 'csv',
        csvText,
      });
      if (!response?.success) {
        throw new Error(response?.message || 'Import failed');
      }
      setCsvText('');
      setMessage(response.message || 'Supplier data imported.');
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed');
    } finally {
      setLoading(false);
    }
  };

  const handleSync = async () => {
    setLoading(true);
    setError(null);
    setMessage(null);
    try {
      const response = await apiService.syncSupplierTier1Data();
      if (!response?.success) {
        throw new Error(response?.message || 'Sync failed');
      }
      setMessage(response.message || 'Supplier Tier-1 data synced to purchase transactions.');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Sync failed');
    } finally {
      setLoading(false);
    }
  };

  const coverageLabel = useMemo(() => {
    if (summary?.coveragePct == null) {
      return null;
    }
    return `${summary.coveragePct}% upstream purchases use Tier-1 supplier or activity data`;
  }, [summary?.coveragePct]);

  return (
    <Card variant="outlined" sx={{ mb: 2 }}>
      <CardContent>
        <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1.5 }}>
          <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
            Upstream supplier Tier-1 data
          </Typography>
          <Chip size="small" label="Scope 3 Cat. 1" variant="outlined" color="primary" />
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Register vendors, request them to enroll on Sustainow for a primary-data score, or import
          supplier-verified emission factors to upgrade purchased-goods transactions from spend proxies.
        </Typography>

        {coverageLabel && (
          <Alert severity={summary?.suppliersMissingPrimaryData ? 'warning' : 'success'} sx={{ mb: 2 }}>
            {coverageLabel}
            {summary?.suppliersMissingPrimaryData
              ? ` · ${summary.suppliersMissingPrimaryData} supplier(s) still need primary data.`
              : null}
          </Alert>
        )}

        {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
        {message && <Alert severity="success" sx={{ mb: 2 }}>{message}</Alert>}
        {inviteUrl && (
          <Alert severity="info" sx={{ mb: 2 }}>
            Invite link: {inviteUrl}
          </Alert>
        )}

        <Stack spacing={2} sx={{ mb: 2 }}>
          <Stack direction={{ xs: 'column', md: 'row' }} spacing={1}>
            <TextField
              label="Supplier legal name"
              value={legalName}
              onChange={(event) => setLegalName(event.target.value)}
              size="small"
              fullWidth
            />
            <TextField
              label="Supplier email (for enroll invite)"
              type="email"
              value={contactEmail}
              onChange={(event) => setContactEmail(event.target.value)}
              size="small"
              fullWidth
            />
            <Button variant="contained" onClick={handleCreateSupplier} disabled={loading || !legalName.trim()}>
              Register supplier
            </Button>
            <Button
              variant="outlined"
              onClick={() => void handleInviteSupplier()}
              disabled={loading || !legalName.trim() || !contactEmail.trim()}
            >
              Request enroll
            </Button>
          </Stack>

          <Stack direction={{ xs: 'column', md: 'row' }} spacing={1}>
            <TextField
              select
              SelectProps={{ native: true }}
              label="Supplier"
              value={selectedSupplierId}
              onChange={(event) => setSelectedSupplierId(event.target.value)}
              size="small"
              fullWidth
            >
              <option value="">Select supplier</option>
              {suppliers.map((supplier) => (
                <option key={supplier._id} value={supplier._id}>
                  {supplier.legalName}
                </option>
              ))}
            </TextField>
            <TextField
              label="kg CO₂e per INR"
              value={factorPerInr}
              onChange={(event) => setFactorPerInr(event.target.value)}
              size="small"
              fullWidth
            />
            <Button variant="outlined" onClick={handleCreateSubmission} disabled={loading}>
              Save factor
            </Button>
          </Stack>

          <TextField
            label="CSV import (supplier_name, emission_factor_kg_co2e_per_inr, ...)"
            value={csvText}
            onChange={(event) => setCsvText(event.target.value)}
            multiline
            minRows={3}
            fullWidth
          />
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <Button
              variant="outlined"
              startIcon={<ImportIcon />}
              onClick={handleImportCsv}
              disabled={loading || !csvText.trim()}
            >
              Import CSV
            </Button>
            <Button
              variant="contained"
              color="secondary"
              startIcon={loading ? <CircularProgress size={18} color="inherit" /> : <SyncIcon />}
              onClick={handleSync}
              disabled={loading}
            >
              Sync to purchase transactions
            </Button>
          </Stack>
        </Stack>

        {(summary?.gaps || []).length > 0 && (
          <Box sx={{ mb: 2 }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1 }}>
              Top supplier gaps
            </Typography>
            <Stack spacing={0.75}>
              {summary?.gaps?.map((gap) => (
                <Typography key={gap.supplierName} variant="body2" color="text.secondary">
                  {gap.supplierName}: {gap.spendProxyTransactions} spend-proxy purchase(s), ₹
                  {Math.round(gap.totalSpendInr).toLocaleString('en-IN')}
                </Typography>
              ))}
            </Stack>
          </Box>
        )}

        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Supplier</TableCell>
              <TableCell>Status</TableCell>
              <TableCell align="right">Submissions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {suppliers.map((supplier) => (
              <TableRow key={supplier._id}>
                <TableCell>{supplier.legalName}</TableCell>
                <TableCell>{supplier.engagementStatus || 'not_contacted'}</TableCell>
                <TableCell align="right">
                  {submissions.filter((item) => {
                    const id = typeof item.supplierId === 'object'
                      ? item.supplierId?._id
                      : item.supplierId;
                    return String(id) === String(supplier._id);
                  }).length}
                </TableCell>
              </TableRow>
            ))}
            {suppliers.length === 0 && (
              <TableRow>
                <TableCell colSpan={3}>
                  <Typography variant="body2" color="text.secondary">
                    No upstream suppliers registered yet.
                  </Typography>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
};

export default SupplierPrimaryDataPanel;
