import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

interface AuditEntry {
  _id?: string;
  eventType?: string;
  summary?: string;
  actorType?: string;
  createdAt?: string;
}

const eventLabel = (type?: string): string => {
  switch (type) {
    case 'recalculation_triggered':
      return 'Recalculation';
    case 'inventory_calculated':
      return 'Inventory calculated';
    case 'inventory_locked':
      return 'Inventory locked';
    case 'boundary_applied':
      return 'Boundary applied';
    case 'factor_registry_updated':
      return 'Factor registry updated';
    default:
      return type?.replace(/_/g, ' ') || 'Event';
  }
};

export const GhgInventoryHistoryPanel: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [entries, setEntries] = useState<AuditEntry[]>([]);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await ApiService.getGhgInventoryAuditLog({ limit: 30 });
        if (cancelled) return;
        setEntries((res?.data?.entries as AuditEntry[]) || []);
      } catch (e) {
        if (!cancelled) {
          setError(e instanceof Error ? e.message : 'Unable to load inventory history');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, []);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  if (error) {
    return <Alert severity="error">{error}</Alert>;
  }

  if (entries.length === 0) {
    return (
      <Alert severity="info">
        No inventory audit events recorded yet. Events appear when boundaries, factors, or
        recalculation policies change.
      </Alert>
    );
  }

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Inventory history
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Append-only audit trail for GHG inventory governance (ISO 14064).
        </Typography>
        <List dense>
          {entries.map((entry) => (
            <ListItem key={entry._id || `${entry.createdAt}-${entry.summary}`} alignItems="flex-start" disableGutters>
              <ListItemText
                primary={
                  <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                    <Chip size="small" label={eventLabel(entry.eventType)} variant="outlined" />
                    <Typography variant="body2">{entry.summary}</Typography>
                  </Stack>
                }
                secondary={
                  entry.createdAt
                    ? `${new Date(entry.createdAt).toLocaleString()} · ${entry.actorType || 'system'}`
                    : undefined
                }
              />
            </ListItem>
          ))}
        </List>
      </CardContent>
    </Card>
  );
};

export default GhgInventoryHistoryPanel;
